function profile_linearized_inner
% Diagnostic only: first five outer iterations of the expensive rejected
% sliding alternative. Not included in trajectory benchmark timing.
[root,~]=setup_tsfs;addpath(fullfile(root,'experiments','inclined_wall'));a=load(fullfile(root,'results','runs','inclined_wall_rotation_20261010','truth.mat'));b=load(fullfile(root,'results','runs','inclined_rotation_linearized_20261011_v2','comparison.mat'),'runs');frames=tsfs.read_input(a.input);fr=frames{19};fr.CU=eye(numel(fr.u))*1e-8;fr.previous.CU=fr.CU;previous=b.runs{1,18};g=b.runs{1,19}.geometry;o=tsfs.defaults;cfg=linearized_mode_settings;cfg.linearization.maxOuterIterations=5;[z,scale,prior]=tsfs.initialize(fr,g,previous,o);cfg.sharedModel=tsfs.linearized_model(fr,g,z,scale,prior,previous,o);
profile clear;profile on;sol=tsfs.linearized_mode_branch(fr,g,previous,o,cfg,2,z,scale,prior);profile off;info=profile('info');[~,ix]=sort([info.FunctionTable.TotalTime],'descend');top=info.FunctionTable(ix(1:min(20,numel(ix))));rows=struct('FunctionName',{top.FunctionName},'TotalTime',num2cell([top.TotalTime]),'NumCalls',num2cell([top.NumCalls]));disp(struct2table(rows));folder=fullfile(root,'results','runs','linearized_modes_20261011');save(fullfile(folder,'profile_rejected_sliding.mat'),'info','sol','-v7.3');atomic_write_artifact(fullfile(folder,'profile_rejected_sliding.json'),'json',rows);
end
